								<text>¥</text>
								<text class="jiage">{{detail.goods_price}}</text>
							</view>
							<view class="center">
								<text class="market-price" v-if="false">市场价:¥{{detail.market_price}}</text>
								<text class="sales_sum">已售:{{detail.sales_sum}}</text>
							</view>
							<view class="right" v-if="false">
								<image src="@/static/common/weixin.png" mode="widthFix" class="wx-img" />
								<text>分享</text>
							</view>
						</view>
						<view class="goods-name">{{detail.goods_name}}</view>
						<view class="goods-remark" v-if="detail.goods_remark">{{detail.goods_remark}}</view>
					</view>
				</view>
				<view class="detail">
					<view class="title">
						<text class="line"></text>
						<text class="text">商品信息</text>
						<text class="line"></text>
					</view>
					<view class="goods-info">
						<view class="goods-info-row">
							<view class="left">品名</view>
							<view class="right">{{detail.goods_name}}</view>
						</view>
						<view class="goods-info-row" v-if="detail.expiration">
							<view class="left">保质期</view>
							<view class="right">{{detail.expiration}}</view>
						</view>
					</view>
					<view class="detail-info" v-html="detail.goods_content">
						<web-view :src="goods_web_url" v-if="false"></web-view>
					</view>
				</view>
				<view :style="{
					'height':`calc(140rpx + ${safe_bot}px)`
				}"></view>
			</view>
			<view class="bottom">
				<view class="bottom-container">
					<view class="left">
						<!-- #ifdef MP-WEIXIN -->
						<button class="left-item" open-type="contact">
							<image src="@/static/index/kefu.png" class="left-item-img" mode="widthFix"/>
							<view>客服</view>
						</button>
						<!-- #endif -->
						<!-- #ifndef MP-WEIXIN -->
						<view class="left-item" @click="goIndex">
							<image src="/static/index/shouye.png" class="left-item-img" mode="widthFix"/>
							<view>首页</view>
						</view>
						<!-- #endif -->
						<view class="left-item" @click="collect_goods">
							<image :src="is_shoucang==1?'/static/index/shoucang_selected.png':'/static/index/shoucang.png'" class="left-item-img" mode="widthFix"/>
							<view>收藏</view>
						</view>
						<button class="left-item" open-type="share" v-if="user_id > 0">
							<image src="/static/index/fenxiang.png" class="left-item-img" mode="widthFix"/>
							<view>分享</view>
						</button>
						<button class="left-item" @click="showLogin" v-else>
							<image src="/static/index/fenxiang.png" class="left-item-img" mode="widthFix"/>
							<view>分享</view>
						</button>
					</view>
					<view class="right">
						<button class="join-cart" @click="buy(1)">加入购物车</button>
						<button class="buy-now" @click="buy(2)">立即购买</button>
					</view>
				</view>
				<view :style="{'height':safe_bot + 'px'}"></view>
			</view>
		</block>
		<u-popup
		:show="bottomShow" 
		@close="bottomShow=false" 
		mode="bottom" 
		bgColor="transparent"
		:overlayOpacity="0.4">
			<view class="goods-bottom">
				<view class="goods-bottom-top">
					<image :src="spec_img" class="top-img" mode="aspectFill"/>
					<view class="center">
						<view class="goods-name">{{detail.goods_name}}</view>
						<view class="goods-store-count">库存{{store_count}}件</view>
						<view class="goods-price">
							<text>¥</text>
							<text class="jiage">{{price}}</text>
						</view>
					</view>
					<image @click="bottomShow=false" src="@/static/common/close-circle.png" class="close-img" mode="widthFix"/>
				</view>
				<view class="goods-bottom-items" v-if="filter_spec.length>0">
					<view class="goods-bottom-item" v-for="(item,index) in filter_spec" :key="index">
						<view class="title">{{item.name}}</view>
						<view class="items">
							<view class="item" @click="changeItem(item,child)" v-for="(child,childIndex) in item.child" :key="childIndex" :class="{'active':item.selected==child.id}">{{child.item}}</view>
						</view>
					</view>
				</view>
				<view class="number-box">
					<view class="left">购买数量</view>
					<view class="right">
						<text :class="{'dis':goods_num<=1}" @click="changeNum(-1)">-</text>
						<text class="number">{{goods_num}}</text>
						<text :class="{'dis':goods_num>=store_count}" @click="changeNum(1)">+</text>
					</view>
				</view>
				<view class="goods-bottom-btns">
					<button class="buy-now" @click="join_cart()" :disabled="store_count<=0" v-if="buy_type == 1">{{store_count<=0?'库存不足':'确定'}}</button>
					<button class="buy-now" @click="buy_now" :disabled="store_count<=0" v-else>{{store_count<=0?'库存不足':'立即购买'}}</button>
				</view>
			</view>
		</u-popup>
		<u-popup
		:show="shareShow" 
		@close="shareShow=false" 
		mode="bottom" 
		bgColor="transparent"
		:overlayOpacity="0.4">
			<view class="share-bottom">
				<view class="share-container">
					<button class="share-item" open-type="share">
						<image src="@/static/index/weixin.png" mode="widthFix" class="share-icon"></image>
						<text>发送给朋友</text>
					</button>
					<button class="share-item" @click="fx_poster">
						<image src="@/static/index/sqhb.png" mode="widthFix" class="share-icon"></image>
						<text>分享商品海报</text>
					</button>
				</view>
				<button class="cancel-btn" @click="shareShow=false">取消</button>
			</view>
		</u-popup>
		
		<wxLogin ref="wx_login" @loginAfter="loginAfter"></wxLogin>
	</view>
</template>

<script>
	import wxLogin from "@/components/wx-login/wx-login.vue"
	var _this;
	function sortNumber(a,b)
	{
		return a - b
	}
	export default {
		data() {
			return {
				//导航栏高度
				navBarHeight: 44,
				statusbarH:0,
				goods_id: 0,
				store:{},
				tj_goods:[],
				all_comment:'',
				comment_list:[],
				current:0,
				select_comment:0,
				page:1,
				pageNum:20,
				titles:[],
				is_shoucang:0,
				goods_num:1,
				filter_spec:[],
				spec_goods_price:[],
				bottomShow:false,
				shareShow:false,
				buy_type:0,
				goods_imgs:[],
				safe_bot:0
			};
		},
		methods: {
			showLogin(){
				_this.$refs.wx_login.loginShow = true
			},
			async login(){
				uni.login({
				  provider: 'weixin',
				  onlyAuthorize:true,
				  success(loginRes) {
					_this.wx_login(loginRes.code)
				  },fail(fail) {
					console.log(fail)
				  }
				});
			},
			loginAfter(result){
				console.log('loginAfter',result);
			},
			async wx_login(code){
				let res = {'code':code}
				const data = await _this.$post('port/get_wx_xcx_data',res)
				if(data.code==200){
					let unionid=data.result.unionid
					let openid=data.result.xcx_openid
					let sessionKey=data.result.sessionKey
					if (unionid) {
						uni.setStorageSync('unionid',unionid)
					}
					uni.setStorageSync('openid',openid)
					uni.setStorageSync('sessionKey',sessionKey)
				}
			},
			fx_poster(){
				uni.navigateTo({
					url:`/pages/index/goods-share?id=${_this.goods_id}`
				})
			},
			onstoptouchmove(){
				return false;
			},
			changeItem(item,child){
				if(child.id==item.selected){
					return
				}
				item.selected = child.id
			},
			buy(type){
				if (_this.user_id == 0) {
					_this.$refs.wx_login.loginShow = true
					return
				}
				_this.buy_type=type
				_this.bottomShow=true
			},
			//加入购物车
			async join_cart(){
				const params = {
					goods_id: _this.goods_id,
					goods_num: _this.goods_num,
					item_id: _this.item_id,
				}
				const data = await _this.$post('port/add_cart', params)
				if(data.code==200){
					_this.bottomShow=false
					this.$u.toast(data.msg)
				}else{
					this.$u.toast(data.msg)
				}
			},
			//立即购买
			buy_now(){
				var url = `/pages/cart/cart-submit?goods_id=${_this.goods_id}&item_id=${_this.item_id}&goods_num=${_this.goods_num}&action=buy_now`;
				_this.toNext(url)
			},
			changeNum(step){
				var max=_this.store_count;
				var number=parseInt(_this.goods_num)+step
				if (step<0){
					if(number<1){
						return
					}
					_this.goods_num=number
				}else {
					if (number>max){
						return;
					}
					_this.goods_num=number
				}
			},
			changeSwiper(current){
				if(_this.current==current){
					return
				}
				_this.current=current
			},
			async get_shangpin_xq() {
				const params = {
					goods_id: _this.goods_id,
				}
				const data = await _this.$post('port/goods_xq', params)
				if (data.code == 200) {
					_this.detail = data.result.goods
					_this.goods_imgs = data.result.goods_imgs
					_this.is_shoucang=data.result.edit
					_this.filter_spec=data.result.filter_spec
					_this.spec_goods_price=data.result.spec_goods_price
					// _this.goods_web_url = `${_this.baseUrl}/port/web_shangpin_xq?goods_id=${_this.goods_id}`
				} else {
					this.$u.toast(data.msg)
				}
				if (_this.load) {
					_this.load = false
				}
			},
			//收藏商品
			async collect_goods(){
				if (_this.user_id == 0) {
					_this.$refs.wx_login.loginShow = true
					return
				}
				const params = {
					goods_id: _this.goods_id,
				}
				const data = await _this.$post('port/edit_shoucang', params)
				if(data.code==200){
					this.$u.toast(data.msg)
					_this.is_shoucang = _this.is_shoucang==1?0:1
				}else{
					this.$u.toast(data.msg)
				}
			},
			lookImg(item,imgIndex){
				uni.previewImage({
					urls:item.full_img,
					current:imgIndex
				})
			},
			//跳转到购物车界面
			goCart(){
				uni.switchTab({
					url:'/pages/cart/cart'
				})
			}
		},
		onLoad(e) {
			_this = this;
			if (e.goods_id || e.scene) {
				if (e.scene) {
					let scene=decodeURIComponent(e.scene);
					let res=scene.split('&')
					let arr = res[0].split('=')
					let brr = res[1].split('=')
					if(brr[1]){
						_this.goods_id = brr[1]
					}
				}else if (e.goods_id) {
					_this.goods_id = e.goods_id
				}
				if(_this.goods_id == '' || _this.goods_id == undefined){
					this.$u.toast('提交参数有误',()=>{
						_this.finish()
					})
					return;
				}
			}else{
				this.$u.toast('提交参数有误',()=>{
						_this.finish()
					})
				return;
			}
			// if (e.goods_id != '' && e.scene != '') {
			// 	if (e.scene) {
			// 		let scene=decodeURIComponent(e.scene);
			// 		let res=scene.split('&')
			// 		let arr = res[0].split('=')
			// 		let brr = res[1].split('=')
			// 		if(brr[1]){
			// 			_this.goods_id = brr[1]
			// 		}
			// 	}else if (e.goods_id) {
			// 		_this.goods_id = e.goods_id
			// 	}
			// 	if(_this.goods_id == '' || _this.goods_id == undefined){
			// 		this.$u.toast('提交参数有误')
			// 		setTimeout(() => {
			// 			uni.navigateBack()
			// 		}, 2000)
			// 		return;
			// 	}
			// } else {
			// 	this.$u.toast('提交参数有误')
			// 	setTimeout(() => {
			// 		uni.navigateBack()
			// 	}, 2000)
			// 	return;
			// }
			let sysInfo = uni.getSystemInfoSync();
			_this.safe_bot = sysInfo.safeAreaInsets.bottom
			_this.statusbarH=sysInfo.statusBarHeight
			// #ifdef MP-WEIXIN
			// 胶囊信息
			let menu = uni.getMenuButtonBoundingClientRect();
			// 导航栏高度
			let navBarHeight = menu.height + 10;
			this.navBarHeight = navBarHeight
			_this.login()
			// #endif
			_this.get_shangpin_xq()
			// _this.get_shangpin_pinglun()
		},
		onShareAppMessage() {
			return {
				title:_this.detail.goods_name,
				path:`/pages/index/goods-detail?goods_id=${_this.detail.goods_id}`,
				imageUrl:_this.detail.goods_img
			}
		},
		computed: {
			bottom_class:{
				cache:false,
				get() {
					if(this.current==0){
						return 'bottom-act'
					}
					return ''
				}
			},
			price:{
				cache:false,
				get(){
					if(this.sort_key==-1){
						return this.detail.goods_price
					}
					return this.spec_goods_price[this.sort_key]['price']
				}
			},
			store_count:{
				cache:false,
				get(){
					if(this.sort_key==-1){
						return this.detail.store_count
					}
					return this.spec_goods_price[this.sort_key]['store_count']
				}
			},
			item_id:{
				cache:false,
				get() {
					if(this.sort_key==-1){
						return 0
					}
					return this.spec_goods_price[this.sort_key]['item_id']
				}
			},
			sort_key:{
				cache:false,
				get(){
					if (this.filter_spec.length>0) {
						var sel=[];
						for (let i = 0; i < this.filter_spec.length; i++) {
							let item = this.filter_spec[i]
							for (let j = 0; j < item.child.length; j++) {
								let child = item.child[j]
								if(child.id==item.selected){
									sel.push(child.id)
								}
							}
						}
						let key = sel.sort(sortNumber).join('_')
						var sort_key = -1
						for (let i = 0; i < this.spec_goods_price.length; i++) {
							let item = this.spec_goods_price[i]
							if(item.key==key){
								sort_key = i
								break
							}
						}
						return sort_key
					}
					return -1;
				}
			},
			item_str:{
				cache:false,
				get() {
					if(this.filter_spec.length<=0){
						return `${this.goods_num}${this.detail.piece}`
					}
					var str = ''
					for (let i = 0; i < this.filter_spec.length; i++) {
						let item = this.filter_spec[i]
						for (let j = 0; j < item.child.length; j++) {
							let child = item.child[j]
							if(child.id==item.selected){
								str+=child.item + ' '
							}
						}
					}
					return `${str}${this.goods_num}${this.detail.piece}`
				}
			},
			spec_img:{
				cache:false,
				get() {
					if(this.filter_spec.length<=0){
						return this.detail.goods_img
					}
					var goods_full_img = ''
					for (let i = 0; i < this.filter_spec.length; i++) {
						let item = this.filter_spec[i]
						var hasImg = false
						for (let j = 0; j < item.child.length; j++) {
							let child = item.child[j]
							if(child.id==item.selected){
								goods_full_img = child.image
								if(goods_full_img){
									hasImg = true
									break;
								}
							}
						}
						if(hasImg){
							break
						}
					}
					return goods_full_img ? goods_full_img : this.detail.goods_img
				}
			}
		},
		components:{
			wxLogin
		},
	}
</script>

